const _txtLead = String(previo.texto || '').toLowerCase();

// ── R10: no arrastrar productos de turnos anteriores ─────────────────────────────────
// En B5 el lead pide pantuflas y recibe TAMBIÉN el catálogo y el video de sandalias: venían
// del turno anterior, `Products` los deja en la lista y W3 los devuelve. El viejo manda sólo
// material de pantuflas. (El orden observado en B5 es exactamente el ORDER BY de W3 para
// ['pantuflas','sandalias'], o sea que el término SOBRA, no falta.)
//
// ⚠️ Sólo se filtra si el mensaje ACTUAL nombra algún producto. Si no nombra ninguno
// ("cuánto cuestan?", "dale"), el arrastre es CORRECTO: el lead se refiere a lo último
// ofrecido, y es lo que sostienen B4 y el bloque "Sugerencia anterior" de `Products`.
// Filtrar ahí rompería las dos cosas.
//
// Y si el filtro dejaría la lista VACÍA se conserva la original: cubre "todos menos
// cilindros", donde el canonicalizador ya excluyó el producto y el texto igual lo nombra.
const _FAM = [
  ['sandalias', /sandalia|zandalia|sandalea|chancla/],
  ['cilindros', /cilindro|silindro/],
  ['mandiles',  /mandil|delantal/],
  ['anticruda', /anticrud|anticrur|costalit|costale|costal\b/],
  ['pantuflas', /pantufla|pantus|pantofla/],
  ['vasos',     /vaso|popote/],
];
const _nombradas = _FAM.filter(([, re]) => re.test(_txtLead)).map(([f]) => f);
if (_nombradas.length) {
  const _famDe = (p) => (_FAM.find(([, re]) => re.test(String(p).toLowerCase())) || [null])[0];
  const _soloPedidos = productos.filter(p => _nombradas.includes(_famDe(p)));
  if (_soloPedidos.length && _soloPedidos.length !== productos.length) {
    console.log('R10 arrastre recortado:', productos, '->', _soloPedidos, '| nombradas:', _nombradas);
    productos = _soloPedidos;
  }
}

const _pidioMaterial = /peluche|satin|sat[ií]n/.test(_txtLead);
